import React from 'react';

const WelcomeBanner = () => {
  return (
    <div className="mb-8 rounded-2xl bg-gradient-to-r from-primary-500 to-secondary-500 p-6 text-white shadow-lg">
      <div className="flex flex-col md:flex-row md:items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold mb-2">Bon retour, Enzo ! 👋</h1>
          <p className="opacity-90">Voici ce qui se passe dans votre boutique aujourd'hui.</p>
        </div>
        <div className="mt-4 md:mt-0">
          <div className="flex items-center space-x-2">
            <div className="px-4 py-2 bg-white/20 rounded-xl backdrop-blur-sm">
              <span className="text-sm">Dernière connexion : Aujourd'hui à 09:42</span>
            </div>
            <button className="px-4 py-2 bg-white text-primary-600 font-medium rounded-xl hover:bg-white/90 transition-colors">
              Voir rapport
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default WelcomeBanner;
